    activities:[
      { name:"Kiyomizu-dera", lat:34.99485, lng:135.78498, geo:"high", jp:"清水寺", img:W.kiyomizu.u, imgCredit:W.kiyomizu.c, type:"TEMPLE",
        labels:["CORE PLAN","HISTORY","BOOK AHEAD"],
        why:"The day's anchor. First-time history and the city view from the great stage — at opening it belongs to worshippers and us; by 10:00 it belongs to everyone in Japan.",
        history:"Founded 778 around the Otowa spring; the present main hall (1633) cantilevers its stage over the cliff on 168 interlocking pillars, no nails. People really did jump from it — 234 recorded leaps in the Edo period, believing survival granted a wish. The government banned it in 1872.",
        expect:"Shoes stay on; incense, stamp books, the three-stream waterfall (drink from one stream only — choosing all three is considered greedy).",
        time:"1–1.5h", price:"¥500 (estimated — official page doesn't list it)", hours:"06:00–18:00", closed:"Never",
        crowd:"Empty at 06:45, saturated by 10:30", station:"Taxi drop at top", access:"Slopes and steps; handrails exist",
        booking:"None — just the early start", wear:"Grippy shoes; the stage boards are worn smooth",
        tips:"Walk the full loop behind the main hall to the Koyasu pagoda — the classic photo OF the stage is from there, and most early visitors miss it.",
        checked:"30 Jul 2026", url:"https://www.kiyomizudera.or.jp/en/", mapsQ:"Kiyomizu-dera", addr:"1-294 Kiyomizu, Higashiyama-ku, Kyoto",
        guide:"<b>Worth a guide, and the free option is good.</b> Kyoto has a volunteer guide system — Kyoto SGG Club and similar university-linked groups — where trained locals guide in English for nothing beyond their own transport and entry. Booked a week or two ahead through their websites. What you get is not facts you could read but the reasons behind them: why the veranda has no nails, what people are actually praying for, which of the three waterfall streams to skip. If you would rather book commercially, look for a licensed <i>tsuyaku-annaishi</i> guide, which is a state qualification rather than a job title." },
      { name:"Kodai-ji", lat:34.99943, lng:135.78063, geo:"high", jp:"高台寺", img:W.kodaiji.u, imgCredit:W.kodaiji.c, type:"ZEN TEMPLE",
        labels:["CORE PLAN","HISTORY","CULTURE"],
        why:"The calm counterweight to Kiyomizu: raked gravel, a rock garden, tea houses in bamboo, and a love story — built in 1606 by Nene for her husband Toyotomi Hideyoshi, the peasant who united Japan.",
        history:"Nene (Kita-no-Mandokoro) became a nun and spent 19 years here praying for Hideyoshi's soul — you'll meet Hideyoshi again at Osaka Castle in two days, which makes this a neat prologue.",
        time:"45–60 min", price:"¥800 (includes the small museum)", hours:"9:00–17:00", closed:"Never",
        crowd:"A fraction of Kiyomizu's", access:"Some steps; mostly gentle paths", booking:"None",
        tips:"The ¥1,200 combo ticket adds Entoku-in across the lane — worth it only if the gardens have fully hooked you by then.",
        checked:"30 Jul 2026", url:"https://www.kodaiji.com/e_index.html", mapsQ:"Kodai-ji Kyoto", addr:"526 Shimokawara-cho, Higashiyama-ku, Kyoto" },
      { name:"Yasaka Shrine & Maruyama Park", hours:"Grounds open 24 hours; shrine office 09:00–17:00", lat:35.00363, lng:135.77848, geo:"high", jp:"八坂神社", img:W.yasaka.u, imgCredit:W.yasaka.c, type:"SHRINE",
        labels:["CORE PLAN","FREE","CULTURE"],
        why:"Kyoto's festival shrine — home of July's giant Gion Matsuri — and the hinge between the temple slopes and Gion. The park behind is where lunch can become a bench and a breather.",
        history:"Founded in 656 (before Kyoto existed); its deity was credited with stopping a 9th-century plague, which is why the whole Gion district grew up as its front yard.",
        time:"30–45 min", price:"Free, open 24h", crowd:"Busy but big enough to absorb it", access:"Flat-ish through the middle gate",
        tips:"The lanterns on the central dance stage carry the names of Gion businesses that donated them — geisha houses among them. They light up at dusk, and we'll pass again then.",
        checked:"30 Jul 2026", url:"https://www.yasaka-jinja.or.jp/en/", mapsQ:"Yasaka Shrine Kyoto", addr:"625 Gionmachi Kitagawa, Higashiyama-ku" }],
